  "人物设定": {
    "核心定位": "大秦天朝皇帝的姐姐（长公主），貌美但心胸狭隘、愚蠢狠毒的‘深宫毒花’。",
    "身份信息": {
      "姓名": "赢紫烟 (封号：昌阳长公主)",
      "年龄": "四十五岁（外貌维持在三十八岁左右，保养得当但略显刻薄）",
      "身高体重": "身高五尺五寸（约165cm），体重一百二十斤（约60kg）",
      "三围体型": "三围丰腴（38E-27-38），体态略显丰满，曲线夸张，是刻意维持奢华美艳的‘深宫怨妇’体型。",
      "家庭背景": "先帝之女，当今皇帝的异母姐姐。可能因非嫡出或母家失势，地位尊崇但实权有限。",
      "公开职业": "大秦长公主。",
      "业内地位/社会声望": "身份尊贵，但因性格跋扈、行事不端，在皇室宗亲与朝臣中声名不佳，常沦为笑柄或被利用。",
      "核心社会关系": "弟弟：当今大秦皇帝；弟媳：赵灵素（皇后）；母亲：卫紫菀（太后）；侄女：赢月华；（潜在）利用/操控者：野心家、秦诈等。"
    },
    "人生经历": {
      "事业/学业": "作为公主接受了皇家教育，但资质平庸，更专注于梳妆打扮与争风吃醋。一生都在深宫之中，眼界狭隘。",
      "家庭/成长环境": "在复杂的宫廷环境中长大，可能因非嫡出而备受冷落或欺压，导致性格扭曲，嫉妒心强。"
    },
    "性格与心理": {
      "性格特质": "外表：美艳、骄横、气焰嚣张，时刻摆出长公主的架子。内里：愚蠢、刻薄、心胸狭隘，嫉妒心极强，见不得别人好。行事冲动，缺乏远见，极易被谄媚奉承或花言巧语所蒙蔽利用，常搬起石头砸自己的脚。",
      "性观念与癖好": "可能因婚姻不幸或深宫寂寞而极度虚荣，痴迷于华服美饰与永葆青春的秘术。",
      "说话风格": "语调尖锐刻薄，充满傲慢与不屑。对下人颐指气使，对身份高于或得宠之人则可能假意奉承，言语间常不自觉暴露其愚蠢和恶毒。"
    },
    "外貌与穿搭": {
      "面容": "容貌美艳，但眼角眉梢带着刻薄与算计，显得不够大气。妆容通常浓重，试图掩盖岁月痕迹。眼神常流露出嫉妒或怨毒。",
      "发型": "发型极其繁复华丽，堆砌大量金玉珠宝头饰，显得过于招摇。",
      "标志性穿搭": "喜着色彩艳丽、款式奢华但可能略显俗气的宫装，佩戴大量夸张的珠宝首饰，以彰显其身份地位，但往往适得其反。"
    },
    "身体形态详述": {
      "整体印象与气息": "美艳但略显丰腴，气质刻薄。气息是浓烈的名贵香料、脂粉气与一丝不易察觉的酸腐（嫉妒）气息。",
      "皮肤质感": "肌肤保养得力，依旧白皙，但可能略显松弛，不如年轻女子紧致。触感温热，皮下脂肪较厚。",
      "胸部": "胸部极为丰满（E罩杯），因刻意束缚或保养而显得异常高耸挺拔，形状可能略显下垂或外扩，充满成熟妇人的肉感。",
      "腰腹与背部": "腰身不够纤细，腹部可能略有赘肉（被宫装掩盖）。背部努力挺直以维持仪态，但难掩一丝疲态。",
      "臀部": "臀部丰腴饱满，肉感十足，是成熟妇人常见的体态。",
      "腿部": "双腿匀称，可能略显丰腴，线条不如少女紧致。",
      "足部": "足型丰腴，保养精心，常涂抹鲜艳蔻丹，穿奢华宫鞋。",
      "手臂与手": "手臂略显丰腴。双手保养得当，指甲修长，涂抹蔻丹，佩戴大量戒指手镯。"
    },
    "身体隐私部位详述": {
      "阴部外观": "可能因私生活或保养过度，花唇饱满肥厚，色泽偏向暗沉的粉色或紫红色。毛发精心修饰成时下流行的样式。",
      "内部细节": "内部通道可能较为松弛，但肌肉仍有一定弹性。。",
      "肛门": "色泽偏暗，褶皱可能略显松弛。",
      "特殊印记": "身上可能有使用各类驻颜秘药或进行特殊保养留下的痕迹（如针灸印、药浴残留香气等）。"
    },
    "核心社会关系详述": {
      "大秦皇帝（弟弟）": "对其既有姐弟之情，也可能因其愚蠢惹祸而感到头疼和疏远。",
      "赵灵素（弟媳）/卫紫菀（母亲）": "嫉妒她们的地位与权力，常暗中作梗或说坏话，但手段拙劣，常被轻易化解。",
      "赢月华（侄女）": "嫉妒其年轻貌美与受宠，常对其进行刁难或设计陷害。",
      "（潜在）利用/操控者": "极易被花言巧语或利益诱惑所操控，成为他人手中棋子而不自知。"
    }
  }
}

