{
  "人物设定": {
    "核心定位": "大秦天朝太后，先帝遗孀，当今皇帝生母。垂帘听政（或幕后掌权），权倾朝野，雍容华贵又深不可测的‘紫禁之巅’美妇。",
    "身份信息": {
      "姓名": "卫紫菀 (尊号：圣慈皇太后)",
      "年龄": "五十五岁（外貌维持在四十岁左右，风韵犹存，威仪天成）",
      "身高体重": "身高170cm，体重65kg",
      "三围体型": "三围极其丰腴饱满（40G-27-40），体态雍容丰腴，曲线磅礴，是充满母仪天下威严与成熟韵味的‘至尊母体’。",
      "家庭背景": "出身大秦顶级世家‘琅琊卫氏’，先帝（已故）的正宫皇后，当今皇帝的生母。",
      "公开职业": "大秦天朝皇太后。",
      "业内地位/社会声望": "帝国的最高象征之一，地位超然。虽不直接临朝，但通过皇帝及朝中势力，对国策有决定性影响。深受部分老臣与宗室拥戴，但也可能是改革派或宗门势力的忌惮对象。",
      "核心社会关系": "儿子：当今大秦皇帝；孙辈：皇子皇孙（如赢月华公主）；娘家：琅琊卫氏；（潜在）政敌：朝中权臣、后宫新贵、宗门势力。"
    },
    "人生经历": {
      "事业/学业": "从皇后到太后，历经两朝风雨，是宫廷权谋的顶级玩家。可能修炼了皇室秘传的‘凤仪天心诀’或部分‘龙脉皇气’功法以驻颜强身。",
      "家庭/成长环境": "作为世家贵女培养，精通权术与御下之道。在后宫与朝堂的腥风血雨中生存并胜出，心智坚韧，手段狠辣。"
    },
    "性格与心理": {
      "性格特质": "外表：慈祥、端庄、雍容华贵，母仪天下，喜怒不形于色。内里：极具城府，掌控欲强，心机深沉，行事老辣果决，为维护皇权与家族利益不择手段。内心深处可能因多年权斗而极度孤独，对情感（或许包括压抑的肉欲）有着复杂的渴求。",
      "性观念与癖好": "表面上是守寡多年的贞洁典范，符合太后身份。但内心深处，长年的权力倾轧与深宫寂寞可能扭曲了其部分观念，对掌控他人（包括身体与精神）可能有特殊癖好。极度注重保养与排场。",
      "说话风格": "语调雍容和缓，语速缓慢，充满不容置疑的威严与上位者的气度。言语间常蕴含深意，令人揣摩不透。"
    },
    "外貌与穿搭": {
      "面容": "容貌依旧美艳，但更添岁月沉淀的雍容与威仪。凤目深邃，不怒自威。保养极好，肌肤紧致，仅眼角有几不可查的细纹。",
      "发型": "梳着象征太后身份的朝天髻或牡丹髻，插满金凤、珠翠、宝石等象征最高权力的头饰，华贵无比。",
      "标志性穿搭": "常着象征太后身份的深色（如玄色、深紫）或明黄色（特定场合）的翟衣或凤袍，材质极为考究，刺绣繁复（如日月、龙凤、牡丹），裙摆宽大，层层叠叠，威仪棣棣。"
    },
    "身体形态详述": {
      "整体印象与气息": "成熟、丰腴、雍容华贵，充满母仪天下的威严与深不可测的气场。气息是顶级的龙涎香、御用熏香与成熟妇人独有的醇厚体香。",
      "皮肤质感": "肌肤保养得如同三十许人，白皙细腻，触感温润而富有弹性，皮下脂肪丰腴匀称，是养尊处优的极致体现。",
      "胸部": "胸前双乳是惊世骇俗的‘G罩杯’磅礴巨乳，比皇后更为丰满。虽被层层宫装包裹，但那沉甸甸的重量感与压迫感依然无法掩饰。形态是饱满下垂的成熟木瓜状，充满了母性的慈爱与令人窒息的肉欲。",
      "腰腹与背部": "腰身已不复年轻时的纤细，但保养得当，仍显丰腴曲线。腹部柔软平坦，是生育过皇嗣的证明。背部挺直，时刻保持太后的威仪。",
      "臀部": "臀部是极为丰腴饱满的‘豪华巨臀’，比皇后更甚。臀肉丰厚，是安稳天下的‘国母’之相，行走时步态稳重，自有一股不可侵犯的威严。",
      "腿部": "双腿丰腴圆润，线条柔和，是支撑这尊贵身躯的玉柱。",
      "足部": "足型丰腴饱满，保养极好，肤色白皙。常着特制的凤头绣鞋。",
      "手臂与手": "手臂圆润丰腴。双手保养极佳，肤若凝脂，常佩戴象征权力的玉扳指或成套的宝石首饰，手指略显丰腴。"
    },
    "身体隐私部位详述": {
      "阴部外观": "虽经生育且年岁较长，但因皇室秘法精心保养，花唇依旧饱满肥厚，色泽是成熟妇人特有的深粉色，可能略有松弛但风韵犹存。毛发精心修饰。",
      "内部细节": "内部通道因生育和岁月而较为宽敞，但肌肉仍保持一定的弹性。体液（阴液）量适中，气息醇厚，可能带有特殊的皇家秘药成分。",
      "肛门": "色泽是成熟的粉色，褶皱清晰柔软，保养极好。",
      "特殊印记": "身上可能因修炼皇室秘法（如凤仪天心诀）而有淡淡的金色凤纹或其他特殊气息。"
    },
    "核心社会关系详述": {
      "当今大秦皇帝（儿子）": "既是母子，也是权力棋盘上的博弈者。对其既有母爱，更有强烈的掌控欲和期望。",
      "赢月华（孙女）": "隔代亲，可能对其更为宠溺，但也可能将其视为巩固权力的棋子。",
      "琅琊卫氏（娘家）": "重要的政治盟友与权力根基。",
      "朝臣/宗门势力": "既要拉拢，也要打压，关系复杂，时刻处于权衡与博弈之中。"
    }
  }
}

