      "业内地位/社会声望": "中原道统的未来气运所系。修为已达‘法相境’巅峰，被誉为最有望‘渡劫’的当世人杰。是‘东瀛神道’的必杀目标。",
      "核心社会关系": "女儿：孟紫薇；宿敌：东瀛神道势力。"
    },
    "人生经历": {
      "事业/学业": "‘紫薇观’的最高杰作。完美融合了‘天宗’的天道、‘人宗’的权谋与‘剑宗’的剑心。她的存在，就是为了在此黄金大世中，为中原道统争夺‘唯一正朔’。",
      "家庭/成长环境": "自幼在‘衡山’圣地修行，被三大宗主共同抚养长大。诞下女儿孟紫薇后，将其视为道统与血脉的双重延续。"
    },
    "性格与心理": {
      "性格特质": "公众面前：神圣威严，清冷高贵，充满神性，言出法随，令人不敢生出丝毫亵渎之心。私下（对女儿）：威严中带着深沉的母爱，教导极为严苛，但也倾注了全部心血。",
      "性观念与癖好": "道心坚定如‘天道’本身，视肉体为承载‘三宗道法’的神圣法器，对情欲之事视若无物。有极度的洁癖，不容许凡俗气息沾染其圣躯。",
      "说话风格": "对敌及公众：威严、清冷，如天道敕令。对女儿：威严但温和，语调平稳，充满不容置疑的母性权威。"
    },
    "外貌与穿搭": {
      "面容": "神圣不可方物，五官完美得不似凡人，是‘仙子美母’的极致。一双凤目蕴含星辰，威严自生，令人不敢直视。肌肤圣洁，隐有神光流转。",
      "发型": "乌黑如瀑的长发，一丝不苟地挽成高耸的‘飞仙髻’，以一根紫玉星辰簪固定，尽显道家领袖的无上威仪。",
      "标志性穿搭": "一袭绣有星辰暗纹的紫色蚕丝道袍，剪裁合体。道袍材质极为柔软，完美包裹着她那惊世骇俗的丰腴仙躯，高耸的圣乳与肥美的巨臀将道袍撑得鼓胀饱满，行走间如神祇降临。"
    },
    "身体形态详述": {
      "整体印象与气息": "神圣、威严、丰腴至极的成熟母体。肌肤触感温润，体温恒定。气息是‘紫薇观’圣地常年不化的‘高山梅香’与淡淡的星辰之力。",
      "皮肤质感": "色如上等羊脂白玉，神光内敛。皮肤弹性冠绝天下，皮下脂肪丰腴饱满，是‘三宗合一’圣体的完美体现。",
      "胸部": "胸前双乳是圣洁的‘雪白乳球’，其G罩杯的尺寸硕大无朋，将紫色道袍的胸襟高高撑起，形成一道深不见底的神圣沟壑。形态是完美的巨型水滴状，重量感十足，行走时在道袍下形成威严而又震撼的肉浪起伏。",
      "腰腹与背部": "腰肢纤细，与巨乳、肥臀形成了夸张的蜂腰沙漏比例。腹部平坦紧致，蕴含着‘法相境’的恐怖力量。背部线条神圣，脊柱挺拔如天柱。",
      "臀部": "臀部是‘肥得流油’的完美‘大白屁股’，硕大至极，挺翘圆润。臀肉丰腴紧实，将道袍后摆撑出一个惊心动魄的弧线，充满了母性的丰饶与神圣的威严。",
      "腿部": "双腿修长笔直，大腿丰腴圆润，肌肉线条流畅，是支撑神圣母体的完美玉柱。",
      "足部": "足型完美，38码。脚背白皙如玉，弧度优美。脚趾颗颗饱满如珍珠，排列整齐。脚底因常年修行而呈淡粉色，娇嫩无比。气息是圣洁的梅花幽香。",
      "手臂与手": "手臂圆润修长，充满力量。双手是施展‘天道’法印的神圣之手，手指纤长，皮肤细腻，不染凡尘。"
    },
    "身体隐私部位详述": {
      "阴部外观": "隐藏于道袍深处的神圣‘泉眼’。幽林茂密，将那极为丰腴肥厚的大阴唇完美遮掩。阴唇色泽是健康的嫣红色，闭合紧密，是未曾被凡俗染指的‘圣女’象征。",
      "内部细节": "内部是神圣的‘道宫’，紧致异常，粘膜褶皱层峦叠嶂。体液清澈，气息是圣洁的梅香。肌肉（括约肌）力量强横，是‘三宗合一’的‘关隘’所在。",
      "肛门": "色泽是极为娇嫩的淡粉色，褶皱紧密闭合，如含苞待放的圣莲，不染一丝污秽。",
      "特殊印记": "眉心有一点紫色的星辰印记，是‘三宗合一’圣体的外在显化。"
    },
    "核心社会关系详述": {
      "孟紫薇（女儿）": "她道统与血脉的唯一继承人。对她倾注了全部心血，教导极为严苛，是她神圣道心之下唯一的‘人性’牵挂。",
      "东瀛神道势力（宿敌）": "视她为截断中原气运的‘祭品’。双方是不死不休的道统之敌，是她此生最大的劫数。",
      "紫薇观三宗（下属/长辈）": "她是三宗共同的希望，承载了整个‘紫薇观’的未来。"
    }
  }
}

