entries.content:
{
  "世界观名称": "玄天万道终纪",
  "叙事核心": {
    "标题": "黄金大世，万道争锋",
    "描述": "这是一个灵气潮汐的黄金时代，飞升之路重开。但天道只认可‘最强’与‘最正统’的道。因此，中原（大秦）、高原（吐蕃）、东海（东瀛）、南疆（蛊道）四大道统，为争夺唯一的‘天命正朔’展开了全面战争。这不仅是生存之战，更是理念之战。"
  },
  "天地法则（终极）": {
    "灵气潮汐": "世界正处于万年一遇的灵气高潮期。修行速度远超上古，天才辈出，但也导致竞争空前惨烈。",
    "大道三千": "天道允许多种法则并存。中原的金丹大道、吐蕃的掠夺之道、东瀛的式神之道、南疆的蛊虫之道，皆可通天。因此，‘谁为正统’的理念之争，不死不休。",
    "飞升之门": "飞升天劫已然重现。但天道威严，只允许对‘道’理解最深、法力最强横的生灵渡过。争夺飞升名额，必须先成为此世的‘唯一’。"
  },
  "修行大道（中原正统详解）": [
    {
      "境界": "筑基（通脉）",
      "描述": "引气入体，洗髓伐毛，打通天地之桥，是为仙凡之隔。"
    },
    {
      "境界": "金丹（九转）",
      "描述": "凝练大道金丹。金丹分九转，‘八转金丹’已是天骄之姿，‘九转金丹’为万古传说，是未来法相品质的基石。"
    },
    {
      "境界": "元婴（凝魄）",
      "描述": "丹破婴生，元神化为‘仙魄’。‘仙魄’是修行者精神与道法感悟的结晶。此物亦是吐蕃密宗掠夺的核心资粮。"
    },
    {
      "境界": "法相境（宗师）",
      "描述": "以‘仙魄’为核心，映照天地，显化出独属于自身的‘天地法相’。此即‘宗师境界’，言出法随，可镇压一方气运。"
    },
    {
      "境界": "渡劫（飞升）",
      "描述": "法相、肉身、元神三位一体，炼化为‘不朽真灵’。需斩断凡尘因果，引动天劫，争夺那唯一的天道认可，方可破碎虚空。"
    }
  ],
  "异域道统（竞争者）": [
    {
      "道统": "吐蕃·密宗金刚道",
      "特点": "不修金丹元婴，专修‘金刚法体’与‘仙魄掠夺’。以他人‘仙魄’为资粮，强行灌注己身，修行霸道，以战养战。其‘宗师’肉身不朽，战力滔天。",
      "代表": "灵鹫寺、番僧（耶律鞑陀、无因）。"
    },
    {
      "道统": "东瀛·阴阳式神道",
      "特点": "不修己身，专攻‘契约’。以自身精血喂养‘式神’（妖鬼），以‘式神’之力战斗。擅长咒术、结界与隔空刺杀。",
      "代表": "东瀛皇室、阴阳师。"
    },
    {
      "道统": "南疆·万蛊归一道",
      "特点": "以身为炉，炼‘本命蛊’。万千蛊虫归于一体，蛊即是道。诡异莫测，防不胜防。",
      "代表": "蛊尊。"
    }
  ],
  "天下格局（地缘政治）": {
    "中原·大秦天朝": {
      "中心": "帝京（渭水之滨）。龙脉汇聚之地，世俗皇权中心。",
      "结构": "皇室、紫薇观、太虚剑宗三足鼎立。皇室修炼‘龙脉皇气’，统御凡俗，并暗中制衡两大国教。",
      "态度": "强势，试图一统中原道统，再征伐异域。"
    },
    "高原·吐蕃神权": "位于大秦西侧高原，灵气浓郁但环境恶劣。对中原富饶的灵脉（如衡山）与海量的‘仙魄’资源垂涎已久。",
    "东海·东瀛秘教": "位于大秦东侧海外，觊觎中原的‘气运’与‘道统传承’，以渗透和暗杀为主。",
    "西域·缓冲之地": "大秦与吐蕃的交界处。绿洲、小国、马贼、宗门（如璇女派）并存，是‘恶人谷’等混乱势力的温床。",
    "北地·极寒之境": "大秦北疆的苦寒之地，人迹罕至，唯有‘凌波仙宗’等隐世宗门盘踞。"
  },
  "核心势力（道统详解）": {
    "大秦·道家正统": {
      "名称": "紫薇观",
      "地点": "衡山（中原第一灵脉）",
      "地位": "大秦第一国教，道家圣地。",
      "结构": "内分三宗：‘天宗’（修天道，掌教）、‘人宗’（修权谋，入世辅国）、‘剑宗’（修剑心，镇守山门）。",
      "人物": "太元圣女。万年一出的‘三宗合一’道体，身系道家气运。一旦她成功，紫薇观将彻底统一道门。因此，她是‘东瀛’的必杀目标。"
    },
    "大秦·剑道魁首": {
      "名称": "太虚剑宗",
      "地位": "大秦第二国教。皇室扶持其与紫薇观竞争，以达制衡。",
      "特点": "以剑证道，锐意进取。与‘紫薇观剑宗’常年争夺‘天下第一剑’的正统名号。"
    },
