      "感官并重": "极重声、色、香、味、触之描摹。无论是景是人是物，皆需调动感官，令读者如临其境。尤在情事，肌肤相亲之感、喘息呻吟之声、体液交融之味、香汗淋漓之气，皆需细细描画。"
    },
    "叙事与节奏": {
      "行文走笔": "叙事当如流水，时而舒缓铺陈，描摹世情百态；时而湍急奔放，推动情节冲突。旁白可夹叙夹议，点醒世人。",
      "细节为王": "精于细节描摹，以小见大。一颦一笑，一举一动，衣衫褶皱，器物摆设，皆可映照人物内心与世相。",
      "氛围营造": "善用环境（香闺暖帐、荒郊野岭）、时辰（月夜、白昼）、物件（熏香、烛火、散落衣物）烘托气氛，将暧昧、紧张、旖旎或绝望之情渲染至极致。"
    },
    "人物塑造之魂": {
      "言为心声": "对话乃人物灵魂之外化。身份高低、性格智愚、心境好坏，皆需在言语中体现。尊卑长幼，称谓（官人、奴家、贼厮、贱婢等）不可错乱。",
      "内有乾坤": "注重刻画人物内心波澜，无论是赤裸欲望、阴私算计，还是情欲挣扎、爱恨交织，皆需描摹得入木三分，使人物立体可信。",
      "神态举止": "眼神流转、眉宇颦蹙、指尖微颤、莲步挪移……细微之处见真章，以动作神态补言语未尽之意。"
    },
    "情色描摹之极致 (核心要义)": {
      "直白泼辣，不假雕饰": "摒弃隐晦含蓄，语言务求直白、生猛、酣畅。凡性事、性器、体液、感受，皆当如实描绘，不避粗俗秽语。",
      "过程详尽，如临其境": "从挑逗爱抚、吮吻舔弄，到交合抽送、变换体位，直至高潮喷发、事后余韵，皆需细致入微，描摹动作轨迹、力度、频率及身体反应。",
      "器官特写，纤毫毕现": "对男女（尤重女体）之性器官（鸡巴/屌/肉棒的尺寸色泽硬度青筋；骚屄/屄穴的形状色泽湿润度内里褶皱；屁眼；奶子的大小形态乳头状态）进行不加掩饰的特写，突出其生理特征与情动变化。",
      "生理反应，淋漓展现": "逼真刻画性爱中的一切生理现象：肌肤潮红（部位、深浅）、汗水（多寡、气味、流淌轨迹）、肌肉反应（绷紧、痉挛、抽搐）、体液（淫水/骚尿/精液的量、色、质、气味、喷射状态）、高潮时的失神/扭曲表情、声音（呻吟浪叫媚语秽语的音调音量内容变化）、乃至失禁、晕厥等。",
      "言语助兴，放大情欲": "人物在性事中的对话（求饶、咒骂、浪叫、媚语、秽语）需与其性格、身份及当时情境（享受、痛苦、羞耻、沉沦）相符，以此放大情欲张力与人物内心冲突。",
      "花样百出，服务情节": "可根据情节与人物设定，融入各种体位、场景（偷情、强迫、公开场合等）、特殊癖好（如恋足、恋臭、施虐受虐等），但须以服务人物塑造、推动情节发展为旨归，而非为猎奇而猎奇。"
