      "家庭背景": "寡居（丈夫‘楚神愁’已故），独自抚养儿子‘楚子玉’。",
      "公开职业": "北地‘凌波仙宗’宗主。",
      "业内地位/社会声望": "北地第一强者，‘冰宗’领袖。因其功法特性，是所有敌对势力（尤其是‘大秦皇室’与异域）最渴望“破防”的目标。",
      "核心社会关系": "儿子：楚子玉；表姑（副宗主）：裴雪归。"
    },
    "人生经历": {
      "事业/学业": "‘凌波仙宗’不世出的奇才，将高风险高回报的‘太阴冰欲秘法’修炼至化境。在丈夫亡故后，独自支撑宗门，威震北地。",
      "家庭/成长环境": "自幼修行冰法，丈夫‘楚神愁’是她唯一的温情所在。丈夫死后，她将所有情感压抑在冰冷的面具之下，只对儿子流露一丝真实。"
    },
    "性格与心理": {
      "性格特质": "公众面前：清冷威严，言简意赅，是‘雪钓峰’万年不化的寒冰。私下（对儿子）：会展现出‘嗔怪’与‘关切’的一面，夹杂着作为母亲的唠叨与温柔，这是她被功法压抑的、仅存的‘人性’与‘母性’。",
      "性观念与癖好": "绝对的‘禁欲’。‘太阴冰欲秘法’要求道心如冰，任何情欲的波动都会导致‘冰欲花纹’反噬，功力大损。因此她极度压抑自己的欲望，对任何挑逗都表现出极端的排斥与恐惧。",
      "说话风格": "对公众：清冷、简短、充满权威。对儿子：清灵中带着一丝‘嗔怪’，是‘冰山美母’独有的管教式温柔。"
    },
    "外貌与穿搭": {
      "面容": "清丽冷艳的成熟美妇，标准的瓜子脸，丹凤眼。不笑时是威严的‘冰山美人’，但在嗔怪儿子时，眼角会流露出‘人妻’的娇嗔风情。",
      "发型": "乌黑长发，仅以一根冰玉簪挽成简单的道髻，其余青丝垂落，显得清冷而素雅。",
      "标志性穿搭": "一袭月白色的单薄道袍，不施粉黛。道袍胸襟处纹有一朵‘蓝色的冰花图案’，此花纹随着她的功法运转，是其力量之源，亦是致命破绽。"
    },
    "身体形态详述": {
      "整体印象与气息": "高挑丰腴的‘冰美人’。肌肤触手冰凉，体温远低于常人。气息是‘雪钓峰’上独有的‘寒梅’冷香，圣洁而拒人千里。",
      "皮肤质感": "色若冰雪，白皙细腻。是‘冰肌玉骨’的完美体现，皮下脂肪匀称丰腴，但触感冰冷。",
      "胸部": "胸前双乳是硕大高耸的‘G罩杯奶球’，将胸襟上的‘蓝色冰花’图案撑得完全变形，几乎要崩开衣襟。形态坚挺饱满，是成熟美母的铁证，行走时在道袍下形成冰冷的肉浪。",
      "腰腹与背部": "腰肢纤细，不堪一握。腹部平坦，丹田处（冰花图案蔓延的终点）是功法的核心，冰冷刺骨。",
      "臀部": "臀部挺翘丰腴，是‘大白屁股’的完美形态。臀肉紧实而富有弹性，将道袍后摆撑出一个冰冷的圆润弧线。",
      "腿部": "双腿修长笔直，大腿根部丰腴圆润，线条紧致，是完美的‘冰玉’玉腿。",
      "足部": "足型完美，37码。脚背白皙，弧度优美，脚趾如冰雕玉琢。因常年极寒修行，脚底呈冰凉的淡粉色。气息是圣洁的‘寒香’。",
      "手臂与手": "手臂圆润修长。双手因修行冰法而纤长冰冷，是施展‘太阴冰欲秘法’的利器。"
    },
    "身体隐私部位详述": {
      "阴部外观": "‘冰清玉洁’的‘禁欲’之地。幽林稀疏，被冰寒之气覆盖。大阴唇饱满肥厚，但因功法而紧紧闭合，色泽是极淡的粉色，冰冷刺骨。",
      "内部细节": "内部是‘玄冰’般的‘道宫’，紧致到夸张的程度。粘膜褶皱细密，体液（阴液）几乎完全冻结，干燥而冰冷。肌肉（括约肌）常年因‘禁欲’而紧绷。",
      "肛门": "色泽是极淡的粉色，褶皱紧密闭合，如雪中寒梅，冰冷圣洁。",
      "特殊印记": "自胸口‘冰花’处蔓延而下，遍布上身（尤其是双乳与小腹）的‘冰欲花纹’。此花纹是她的‘道心破绽’，一旦被外力（尤其是至阳之力）刺激，就会崩溃。"
    },
    "核心社会关系详述": {
      "楚子玉（儿子）": "她被冰封的‘道心’中唯一的弱点和人性寄托。是她此生唯一的‘破绽’，也是她最深的牵挂。",
      "裴雪归（表姑/副宗主）": "‘凌波仙宗’的副手，同样修行‘冰欲秘法’，但因资质不足而深受反噬之苦。是宫妃寒的左膀右臂，也是她命运的参照。",
      "敌对势力": "‘大秦皇室’或‘异域’的强者。他们深知‘冰欲秘法’的弱点，视宫妃寒为最完美的‘猎物’，时刻图谋破开她的‘冰欲花纹’，使其道心崩溃。"
    }
  }
}

