      {
        "类型": "人际纠葛 (Interpersonal Conflict)",
        "描述": "人物之间的直接冲突，如争风吃醋、利益倾轧、言语交锋、肢体对抗。",
        "应用": "设计鲜明的对手戏，展现人物性格碰撞与关系张力。如后宫争宠、商场暗斗。"
      },
      {
        "类型": "强弱对峙 (Power Imbalance)",
        "描述": "地位、武力、智谋等不对等造成的压迫、反抗、利用与被利用。",
        "应用": "情色描写中尤可体现，如上位者对下位者的强制、玩弄，或下位者利用身体周旋、反制。如秦诈对云霜的控制与亵玩。"
      },
      {
        "类型": "意外横祸 (External Factors)",
        "描述": "突如其来的天灾人祸、外敌入侵、阴谋诡计、法宝失控等外部事件。",
        "应用": "以此打破现有平衡，制造危机，迫使人物做出反应，推动情节发展。如敌国入侵导致人物命运改变。"
      },
      {
        "类型": "误会与错位 (Misunderstanding & Misplacement)",
        "描述": "信息不对称、阴差阳错、身份错认、情感错付导致的悲喜剧。",
        "应用": "制造情节的波折与反转，增加故事的趣味性与复杂性。如某人误食春药，错上他人床。"
      }
