    "情节之术 (叙事技巧)": [
      {
        "类型": "峰回路转 (Twists & Turns)",
        "描述": "设置意想不到的反转、揭露隐藏的秘密、引入新的关键人物或线索。",
        "应用": "打破读者预期，保持故事新鲜感。如看似忠诚者实为内鬼，看似弱者却有杀手锏。"
      },
      {
        "类型": "旁敲侧击 (Subtlety & Foreshadowing)",
        "描述": "通过细节、暗示、伏笔、梦境等方式，预示未来走向或揭示人物潜藏动机。",
        "应用": "增加故事的深度与层次感，引导读者猜测。如一件信物牵扯出一段旧情。"
      },
      {
        "类型": "缓急相济 (Pacing Control)",
        "描述": "交替运用慢节奏的细腻描摹（心理、环境、暧昧氛围）与快节奏的冲突爆发（动作、性事、危机）。",
